function push(chunk) {
  if (state.finished || state.poisoned) {
    throw fail('decoder is finished or poisoned');
  }
  validateChunk(chunk);
  let text;
  try {
    text = decoder.decode(chunk, {stream: true});
  } catch (e) {
    state.poisoned = true;
    throw e;
  }
  // Handle BOM: one optional leading BOM is ignored.
  if (!state.bomSeen) {
    state.bomSeen = true;
    if (text.charCodeAt(0) === BOM) {
      text = text.slice(1);
    }
  }
  const frames = [];
  // Process text, splitting on LF.
  const full = state.lineBuf + text;
  state.lineBuf = '';
  let start = 0;
  for (let i = 0; i < full.length; i++) {
    if (full.charCodeAt(i) === 0x0A) {
      let lineEnd = i;
      // Strip one CR immediately preceding LF.
      if (lineEnd > start && full.charCodeAt(lineEnd - 1) === 0x0D) {
        lineEnd--;
      }
      const line = full.slice(start, lineEnd);
      try {
        const frame = parseLine(line, state);
        if (frame !== null) frames.push(frame);
      } catch (e) {
        state.poisoned = true;
        throw e;
      }
      start = i + 1;
    }
  }
  state.lineBuf = full.slice(start);
  return frames;
}

