import('./stream-framer.js').then(({createDecoder})=>{
  // BOM split at 0/37: empty first chunk, then all bytes
  const all=Buffer.concat([Buffer.from([0xEF,0xBB,0xBF]),Buffer.from('data: jig-é😀\r\n\r\ndata: [DONE]\n\n')]);
  const d1=createDecoder();
  const f1=d1.push(new Uint8Array(0));
  const f2=d1.push(all);
  console.log('BOM 0/37:',JSON.stringify(f1.concat(f2)));

  // BOM split at 1/37: one BOM byte, then rest
  const d2=createDecoder();
  const g1=d2.push(all.slice(0,1));
  const g2=d2.push(all.slice(1));
  console.log('BOM 1/37:',JSON.stringify(g1.concat(g2)));

  // BOM split at 3/37: full BOM, then rest
  const d3=createDecoder();
  const h1=d3.push(all.slice(0,3));
  const h2=d3.push(all.slice(3));
  console.log('BOM 3/37:',JSON.stringify(h1.concat(h2)));

  // One-byte chunks with BOM
  const d4=createDecoder();
  const frames=[];
  for(const byte of all) frames.push(...d4.push(Uint8Array.of(byte)));
  console.log('BOM 1-byte:',JSON.stringify(frames));

  // finish after BOM stream
  console.log('finish:',JSON.stringify(d4.finish()));
});
