  const f2a=d2.push(Buffer.from('event: foo\n\n'));
  const f2b=d2.push(Buffer.from('data: bar\n\n'));
  console.log('event leak:',JSON.stringify(f2a.concat(f2b)));

  // Empty data dispatch
