function validateBase64(s) {
  if (typeof s !== 'string') throw fail('chunk must be a string');
  // Canonical standard padded base64: only A-Z, a-z, 0-9, +, /, =
  // '=' can only appear as the last 1 or 2 characters.
  if (!/^[A-Za-z0-9+/]*$/.test(s.replace(/={1,2}$/,''))) throw fail('invalid base64 characters');
  const len = s.length;
  if (len % 4 !== 0) throw fail('invalid base64 length');
  // Check pad bits are zero.
  if (len >= 4) {
    const padCount = (s[len - 1] === '=') ? (s[len - 2] === '=' ? 2 : 1) : 0;
    if (padCount === 1) {
      const val = base64Value(s[len - 2]);
      if (val < 0 || (val & 0x03) !== 0) throw fail('noncanonical pad bits');
    } else if (padCount === 2) {
      const val = base64Value(s[len - 3]);
      if (val < 0 || (val & 0x07) !== 0) throw fail('noncanonical pad bits');
    }
  }
}

