node -e "
import assert from 'node:assert/strict';
import {createDecoder} from './stream-framer.js';

// 1. BOM: all two-part splits of BOM+data stream
const bomAll=Buffer.concat([Buffer.from([0xEF,0xBB,0xBF]),Buffer.from('data: jig-é😀\r\n\r\ndata: [DONE]\n\n')]);
const expected=[{event:'message',data:'jig-é😀'}];
for(let split=0;split<=bomAll.length;split++){
  const d=createDecoder();
  const f=d.push(bomAll.slice(0,split)).concat(d.push(bomAll.slice(split)));
  assert.deepEqual(f,expected,'BOM split '+split);
  assert.deepEqual(d.finish(),[],'finish split '+split);
}

// 2. One-byte chunks with BOM
{
  const d=createDecoder();const fr=[];
  for(const b of bomAll)fr.push(...d.push(Uint8Array.of(b)));
  assert.deepEqual(fr,expected);assert.deepEqual(d.finish(),[]);
}

// 3. Second BOM is ordinary data (unknown field, no frame)
{
  const d=createDecoder();
  assert.deepEqual(d.push(Buffer.from('\uFEFF\uFEFFdata: x\n\n')),[]);
  assert.deepEqual(d.push(Buffer.from('data: [DONE]\n\n')),[]);
  assert.deepEqual(d.finish(),[]);
}

// 4. Incomplete multibyte at finish throws
{
  const d=createDecoder();
  d.push(Buffer.from('data: [DONE]\n\n'));
  d.push(Buffer.from([0xE2]));
  assert.throws(()=>d.finish(),Error);
  assert.throws(()=>d.push(Buffer.from('x\n')),Error);
}

// 5. Incomplete multibyte across pushes (valid)
{
  const d=createDecoder();
  const f=d.push(Buffer.from('data: ')).concat(d.push(Buffer.from([0xC3])),d.push(Buffer.from([0xA9,0x0A,0x0A])),d.push(Buffer.from('data: [DONE]\n\n')));
  assert.deepEqual(f,[{event:'message',data:'é'}]);
  assert.deepEqual(d.finish(),[]);
}

// 6. CR in data preserved
{
  const d=createDecoder();
  assert.deepEqual(d.push(Buffer.from('data: a\rb\n\n')),[{event:'message',data:'a\rb'}]);
  assert.deepEqual(d.push(Buffer.from('data: [DONE]\n\n')),[]);
  assert.deepEqual(d.finish(),[]);
}

// 7. CRLF split across chunks
{
  const d=createDecoder();
  const f=d.push(Buffer.from('data: x\r')).concat(d.push(Buffer.from('\n\n')));
  assert.deepEqual(f,[{event:'message',data:'x'}]);
  assert.deepEqual(d.push(Buffer.from('data: [DONE]\n\n')),[]);
  assert.deepEqual(d.finish(),[]);
}

// 8. Trailing CR alone does not complete a line
{
  const d=createDecoder();
  d.push(Buffer.from('data: x\r'));
  assert.throws(()=>d.finish(),Error);
}

// 9. Event name leak
{
  const d=createDecoder();
  assert.deepEqual(d.push(Buffer.from('event: foo\n\n')),[]);
  assert.deepEqual(d.push(Buffer.from('data: bar\n\n')),[{event:'message',data:'bar'}]);
  assert.deepEqual(d.push(Buffer.from('data: [DONE]\n\n')),[]);
  assert.deepEqual(d.finish(),[]);
}

// 10. Empty data dispatch
{
  const d=createDecoder();
  assert.deepEqual(d.push(Buffer.from('data:\n\n')),[{event:'message',data:''}]);
  assert.deepEqual(d.push(Buffer.from('data: [DONE]\n\n')),[]);
  assert.deepEqual(d.finish(),[]);
}

// 11. data with no colon
{
  const d=createDecoder();
  assert.deepEqual(d.push(Buffer.from('data\n\n')),[{event:'message',data:''}]);
  assert.deepEqual(d.push(Buffer.from('data: [DONE]\n\n')),[]);
  assert.deepEqual(d.finish(),[]);
}

// 12. Unknown field only
{
  const d=createDecoder();
  assert.deepEqual(d.push(Buffer.from('foo: bar\n\n')),[]);
  assert.deepEqual(d.push(Buffer.from('data: [DONE]\n\n')),[]);
  assert.deepEqual(d.finish(),[]);
}

// 13. [DONE] with event name emits nothing
{
  const d=createDecoder();
  assert.deepEqual(d.push(Buffer.from('event: custom\ndata: [DONE]\n\n')),[]);
  assert.deepEqual(d.finish(),[]);
}

// 14. Post-termination: only blank lines allowed
{
  const d=createDecoder();
  d.push(Buffer.from('data: [DONE]\n\n'));
  assert.throws(()=>d.push(Buffer.from(': comment\n')),Error);
  assert.throws(()=>d.push(Buffer.from('data: x\n')),Error);
  assert.throws(()=>d.push(Buffer.from('foo: bar\n')),Error);
  assert.throws(()=>d.push(Buffer.from('data: [DONE]\n\n')),Error);
  assert.throws(()=>d.finish(),Error);
}

// 15. Post-termination: blank lines OK
{
  const d=createDecoder();
  d.push(Buffer.from('data: [DONE]\n\n'));
  assert.deepEqual(d.push(Buffer.from('\n\n')),[]);
  assert.deepEqual(d.finish(),[]);
}

// 16. Rejection poisons: wrong type
{
  const d=createDecoder();
  assert.throws(()=>d.push('string'),Error);
  assert.throws(()=>d.push(Buffer.from('data: x\n\n')),Error);
  assert.throws(()=>d.finish(),Error);
}

// 17. Rejection poisons: invalid UTF-8
{
  const d=createDecoder();
  assert.throws(()=>d.push(Buffer.from([0xFF,0xFE])),Error);
  assert.throws(()=>d.push(Buffer.from('data: x\n\n')),Error);
  assert.throws(()=>d.finish(),Error);
}

// 18. Rejection poisons: nonterminated finish
{
  const d=createDecoder();
  d.push(Buffer.from('data: x'));
  assert.throws(()=>d.finish(),Error);
  assert.throws(()=>d.push(Buffer.from('\n')),Error);
  assert.throws(()=>d.finish(),Error);
}

// 19. Rejection poisons: missing termination
{
  const d=createDecoder();
  d.push(Buffer.from('data: x\n\n'));
  assert.throws(()=>d.finish(),Error);
  assert.throws(()=>d.push(Buffer.from('data: y\n\n')),Error);
}

// 20. Independent decoders
{
  const d1=createDecoder(),d2=createDecoder();
  assert.throws(()=>d1.push('bad'),Error);
  assert.deepEqual(d2.push(Buffer.from('data: ok\n\n')),[{event:'message',data:'ok'}]);
  assert.deepEqual(d2.push(Buffer.from('data: [DONE]\n\n')),[]);
  assert.deepEqual(d2.finish(),[]);
}

// 21. Empty chunks allowed before finish
{
  const d=createDecoder();
  assert.deepEqual(d.push(new Uint8Array(0)),[]);
  assert.deepEqual(d.push(Buffer.from('data: x\n\n')),[]);
  assert.deepEqual(d.push(new Uint8Array(0)),[]);
  assert.deepEqual(d.push(Buffer.from('data: [DONE]\n\n')),[]);
  assert.deepEqual(d.finish(),[]);
}

// 22. Push after finish throws
{
  const d=createDecoder();
  d.push(Buffer.from('data: [DONE]\n\n'));d.finish();
  assert.throws(()=>d.push(new Uint8Array()),Error);
  assert.throws(()=>d.finish(),Error);
}

// 23. finish before any push throws
{
  const d=createDecoder();
  assert.throws(()=>d.finish(),Error);
}

// 24. Never mutate supplied chunk
{
  const d=createDecoder();
  const chunk=Buffer.from('data: x\n\n');
  const copy=new Uint8Array(chunk);
  d.push(chunk);
  assert.deepEqual(new Uint8Array(chunk),copy);
  assert.deepEqual(d.push(Buffer.from('data: [DONE]\n\n')),[]);
  assert.deepEqual(d.finish(),[]);
}

// 25. Multiline data joined with LF
{
  const d=createDecoder();
  assert.deepEqual(d.push(Buffer.from('data: a\ndata: b\ndata: c\n\n')),[{event:'message',data:'a\nb\nc'}]);
  assert.deepEqual(d.push(Buffer.from('data: [DONE]\n\n')),[]);
  assert.deepEqual(d.finish(),[]);
}

// 26. Empty event name falls back to message
{
  const d=createDecoder();
  assert.deepEqual(d.push(Buffer.from('event:\ndata: x\n\n')),[{event:'message',data:'x'}]);
  assert.deepEqual(d.push(Buffer.from('data: [DONE]\n\n')),[]);
  assert.deepEqual(d.finish(),[]);
}

// 27. data:  [DONE] (two spaces) is NOT [DONE]
{
  const d=createDecoder();
  assert.deepEqual(d.push(Buffer.from('data:  [DONE]\n\n')),[{event:'message',data:' [DONE]'}]);
  assert.deepEqual(d.push(Buffer.from('data: [DONE]\n\n')),[]);
  assert.deepEqual(d.finish(),[]);
}

// 28. Comment line has no effect
{
  const d=createDecoder();
  assert.deepEqual(d.push(Buffer.from(': hello\n\n')),[]);
  assert.deepEqual(d.push(Buffer.from('data: [DONE]\n\n')),[]);
  assert.deepEqual(d.finish(),[]);
}

// 29. data: [DONE]x is NOT [DONE]
{
  const d=createDecoder();
  assert.deepEqual(d.push(Buffer.from('data: [DONE]x\n\n')),[{event:'message',data:'[DONE]x'}]);
  assert.deepEqual(d.push(Buffer.from('data: [DONE]\n\n')),[]);
  assert.deepEqual(d.finish(),[]);
}

// 30. data: [DONE] with leading space is NOT [DONE]
{
  const d=createDecoder();
  assert.deepEqual(d.push(Buffer.from('data:  [DONE]\n\n')),[{event:'message',data:' [DONE]'}]);
  assert.deepEqual(d.push(Buffer.from('data: [DONE]\n\n')),[]);
  assert.deepEqual(d.finish(),[]);
}

