import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const BOM = 0xFEFF;

function fail(msg) {
  const e = new Error(msg);
  e.fatal = true;
  return e;
}

function validateChunk(chunk) {
  if (!(chunk instanceof Uint8Array)) {
    throw fail('chunk must be a Uint8Array');
  }
}

function parseLine(line, state) {
  if (line === '') {
    // Blank line: dispatch if there is at least one data field.
    if (state.dataCount > 0) {
      const data = state.data.join('\n');
      let event = state.event;
      if (event === null || event === '') event = 'message';
      if (data === '[DONE]') {
        state.terminated = true;
        state.data = [];
        state.dataCount = 0;
        state.event = null;
        return null;
      }
      state.data = [];
      state.dataCount = 0;
      state.event = null;
      return {event, data};
    }
    // No data fields: reset fields, emit nothing.
    state.data = [];
    state.dataCount = 0;
    state.event = null;
    return null;
  }
  if (state.terminated) {
    // After termination, only blank lines are allowed.
    throw fail('nonblank line after termination');
  }
  if (line[0] === ':') {
    // Comment: no effect.
    return null;
  }
  // Split at first colon.
  const colonIdx = line.indexOf(':');
  let fieldName, fieldValue;
  if (colonIdx === -1) {
    fieldName = line;
    fieldValue = '';
  } else {
    fieldName = line.slice(0, colonIdx);
    fieldValue = line.slice(colonIdx + 1);
    // Remove at most one leading ASCII space.
    if (fieldValue[0] === ' ') {
      fieldValue = fieldValue.slice(1);
    }
  }
  if (fieldName === 'data') {
    state.data.push(fieldValue);
    state.dataCount++;
  } else if (fieldName === 'event') {
    state.event = fieldValue;
  }
  // Other fields are ignored.
  return null;
}

export function createDecoder() {
  const decoder = new TextDecoder('utf-8', {fatal: true, ignoreBOM: true});
  const state = {
    data: [],
    dataCount: 0,
    event: null,
    terminated: false,
    finished: false,
    poisoned: false,
    lineBuf: '',
    bomSeen: false,
  };

  function push(chunk) {
    if (state.finished || state.poisoned) {
      throw fail('decoder is finished or poisoned');
    }
    if (!(chunk instanceof Uint8Array)) {
      state.poisoned = true;
      throw fail('chunk must be a Uint8Array');
    }
    let text;
    try {
      text = decoder.decode(chunk, {stream: true});
    } catch (e) {
      state.poisoned = true;
      throw e;
    }
    const frames = [];
    // Process text, splitting on LF.
    let full = state.lineBuf + text;
    state.lineBuf = '';
    // One optional leading UTF-8 BOM is ignored; it can only be the very
    // first character of the stream, so wait until that character arrives.
    if (!state.bomSeen && full.length > 0) {
      state.bomSeen = true;
      if (full.charCodeAt(0) === BOM) {
        full = full.slice(1);
      }
    }
    let start = 0;
    for (let i = 0; i < full.length; i++) {
      if (full.charCodeAt(i) === 0x0A) {
        let lineEnd = i;
        // Strip one CR immediately preceding LF.
        if (lineEnd > start && full.charCodeAt(lineEnd - 1) === 0x0D) {
          lineEnd--;
        }
        const line = full.slice(start, lineEnd);
        try {
          const frame = parseLine(line, state);
          if (frame !== null) frames.push(frame);
        } catch (e) {
          state.poisoned = true;
          throw e;
        }
        start = i + 1;
      }
    }
    state.lineBuf = full.slice(start);
    return frames;
  }

  function finish() {
    if (state.finished || state.poisoned) {
      throw fail('decoder is finished or poisoned');
    }
    let text;
    try {
      text = decoder.decode();
    } catch (e) {
      state.poisoned = true;
      throw e;
    }
    // Handle BOM in final flush (shouldn't happen, but be safe).
    if (!state.bomSeen) {
      state.bomSeen = true;
      if (text.charCodeAt(0) === BOM) {
        text = text.slice(1);
      }
    }
    // Append final text to lineBuf.
    const full = state.lineBuf + text;
    if (full.length > 0) {
      // Nonterminated final line is an error.
      state.poisoned = true;
      throw fail('nonterminated final line');
    }
    if (!state.terminated) {
      state.poisoned = true;
      throw fail('stream not terminated');
    }
    if (state.dataCount > 0 || state.event !== null) {
      state.poisoned = true;
      throw fail('pending data or event fields at finish');
    }
    state.finished = true;
    return [];
  }

  return {push, finish};
}

function base64Value(c) {
  if (c >= 'A' && c <= 'Z') return c.charCodeAt(0) - 65;
  if (c >= 'a' && c <= 'z') return c.charCodeAt(0) - 71;
  if (c >= '0' && c <= '9') return c.charCodeAt(0) - 55;
  if (c === '+') return 62;
  if (c === '/') return 63;
  return -1;
}

function validateBase64(s) {
  if (typeof s !== 'string') throw fail('chunk must be a string');
  // Canonical standard padded base64: only A-Z, a-z, 0-9, +, /, =
  // '=' can only appear as the last 1 or 2 characters.
  if (!/^[A-Za-z0-9+/]*$/.test(s.replace(/={1,2}$/,''))) throw fail('invalid base64 characters');
  const len = s.length;
  if (len % 4 !== 0) throw fail('invalid base64 length');
  // Check pad bits are zero.
  if (len >= 4) {
    const padCount = (s[len - 1] === '=') ? (s[len - 2] === '=' ? 2 : 1) : 0;
    if (padCount === 1) {
      const val = base64Value(s[len - 2]);
      if (val < 0 || (val & 0x03) !== 0) throw fail('noncanonical pad bits');
    } else if (padCount === 2) {
      const val = base64Value(s[len - 3]);
      if (val < 0 || (val & 0x07) !== 0) throw fail('noncanonical pad bits');
    }
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    if (process.argv.length !== 3) throw fail('usage: stream-framer.js INPUT_JSON_FILE');
    const input = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
    if (input === null || typeof input !== 'object' || Array.isArray(input)) throw fail('input must be a non-null non-array object');
    if (!Array.isArray(input.chunks)) throw fail('chunks must be an array');
    const decoder = createDecoder();
    const frames = [];
    for (const encoded of input.chunks) {
      validateBase64(encoded);
      frames.push(...decoder.push(Buffer.from(encoded, 'base64')));
    }
    frames.push(...decoder.finish());
    process.stdout.write(JSON.stringify({frames}) + '\n');
  } catch (error) {
    process.stderr.write(String(error.message) + '\n');
    process.exitCode = 2;
  }
}

